// Stub 'electron' untuk sidecar Node (fase A/B migrasi Tauri).
// Menangkap import modul main lama; perilaku nyata digantikan:
//  - shell.openExternal / openPath -> xdg-open
//  - dialog -> dibatalkan (canceled) sampai port ke tauri-plugin-dialog
//  - BrowserWindow/Tray/Notification -> no-op object aman
import { spawn } from 'child_process'
import os from 'os'
import path from 'path'

const openExternal = (url) =>
  new Promise((resolve) => {
    try {
      spawn('xdg-open', [String(url)], { detached: true, stdio: 'ignore' }).unref()
    } catch {}
    resolve()
  })

const paths = {
  home: os.homedir(),
  temp: os.tmpdir(),
  documents: path.join(os.homedir(), 'Documents'),
  downloads: path.join(os.homedir(), 'Downloads'),
  userData: path.join(os.homedir(), '.local', 'share', 'mark'),
  appData: path.join(os.homedir(), '.local', 'share')
}

